div.script:
(function () {
  var tallyEl = document.getElementById('ff-mood-tally');
  if (!tallyEl) return;

  function loadTally() {
    fetch('/radio/votes/summary', { cache: 'no-store' })
      .then(function (r) { return r.json(); })
      .then(function (data) {
        if (!data || !data.ok) return;
        var c = data.counts || {};
        var energy = c.energy || 0;
        var chill = c.chill || 0;
        var banger = c.like || 0;
        var total = energy + chill + banger;
        if (!total) {
          tallyEl.textContent = 'Noch keine Stimmen in den letzten 30 Minuten — sei die erste Person';
          return;
        }
        tallyEl.textContent = 'Letzte 30 Min: ⚡ ' + energy + ' · ❤️ ' + banger + ' · 🌙 ' + chill;
      })
      .catch(function () {});
  }

  loadTally();
  setInterval(loadTally, 20000);

  ['ff-mood-energy', 'ff-mood-chill'].forEach(function (id) {
    var btn = document.getElementById(id);
    if (btn) btn.addEventListener('click', function () { setTimeout(loadTally, 1500); });
  });

  window.ffShowReaction = function (emoji) {
    if (window.spawnReaction) window.spawnReaction(emoji);
  };

  var ffRedaktionLiveFlag = false;

  window.ffSetLiveMode = function (isLive) {
    var wasLive = ffRedaktionLiveFlag;
    ffRedaktionLiveFlag = Boolean(isLive);
    var redaktionBlock = document.getElementById('ff-redaktion');
    if (isLive) {
      if (redaktionBlock) redaktionBlock.style.display = 'none';
    } else if (wasLive) {
      if (window.ffLoadRedaktion) window.ffLoadRedaktion();
    }

    var voteGrid = document.querySelector('.ff-mood-grid');
    var showGrid = document.getElementById('ff-show-reactions');
    if (!voteGrid) return;
    if (!showGrid) return;
    if (isLive) {
      voteGrid.style.display = 'none';
      showGrid.style.display = '';
      if (tallyEl) tallyEl.textContent = 'Live-Show läuft — der DJ übernimmt';
      return;
    }
    voteGrid.style.display = '';
    showGrid.style.display = 'none';
  };

  function ffPaintRedaktionActive(art, wert) {
    var btns = document.querySelectorAll('.ff-redaktion-btn');
    btns.forEach(function (b) {
      if (b.getAttribute('data-art') !== art) return;
      var v = b.getAttribute('data-wert');
      var match = false;
      if (wert !== null) {
        if (wert !== undefined) {
          match = (v === String(wert));
        }
      }
      if (match) {
        b.classList.add('active');
      } else {
        b.classList.remove('active');
      }
    });
  }

  window.ffLoadRedaktion = function () {
    var block = document.getElementById('ff-redaktion');
    if (!block) return;
    var key = window.currentTrackKey || '';
    if (!key) {
      block.style.display = 'none';
      return;
    }
    if (key === 'FraWo Funk') {
      block.style.display = 'none';
      return;
    }
    if (ffRedaktionLiveFlag) {
      block.style.display = 'none';
      return;
    }
    var sendung = window.ffCurrentSendung || '';
    fetch('/radio/redaktion/info?track_id=' + encodeURIComponent(key), { cache: 'no-store' })
      .then(function (r) { return r.json(); })
      .then(function (d) {
        if (!d) return;
        if (!d.ok) return;
        if (!d.redakteur) {
          block.style.display = 'none';
          return;
        }
        if (ffRedaktionLiveFlag) {
          block.style.display = 'none';
          return;
        }
        if (key !== window.currentTrackKey) return;
        block.setAttribute('data-track', key);
        block.setAttribute('data-sendung', sendung);
        var label = document.getElementById('ff-redaktion-sendung-label');
        if (label) {
          if (sendung) {
            label.textContent = 'Passt in ' + sendung + '?';
          } else {
            label.textContent = 'Passt das?';
          }
        }
        var feedback = document.getElementById('ff-redaktion-feedback');
        if (feedback) feedback.textContent = '';
        var eigene = d.eigene || {};
        ffPaintRedaktionActive('energie', eigene.energie);
        ffPaintRedaktionActive('passt', eigene.passt);
        block.style.display = '';
      })
      .catch(function () {
        block.style.display = 'none';
      });
  };

  window.ffJudge = function (btn) {
    if (!btn) return;
    var art = btn.getAttribute('data-art') || '';
    if (!art) return;
    var wert = parseInt(btn.getAttribute('data-wert'), 10);
    var block = document.getElementById('ff-redaktion');
    if (!block) return;
    var track = block.getAttribute('data-track') || '';
    if (!track) return;
    var sendung = block.getAttribute('data-sendung') || '';
    var feedback = document.getElementById('ff-redaktion-feedback');
    if (feedback) feedback.textContent = 'speichert…';
    fetch('/radio/redaktion/urteil', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ track_id: track, art: art, wert: wert, sendung: sendung })
    }).then(function (r) {
      if (!r.ok) {
        if (feedback) feedback.textContent = 'nicht gespeichert';
        return;
      }
      if (feedback) feedback.textContent = 'gespeichert';
      ffPaintRedaktionActive(art, wert);
    }).catch(function () {
      if (feedback) feedback.textContent = 'nicht gespeichert';
    });
  };

  var starsEl = document.getElementById('ff-stars');
  var ratingSub = document.getElementById('ff-rating-sub');
  var ratingBox = document.getElementById('ff-rating-box');

  function ffIsLoggedIn() {
    var s = (window.odoo && (window.odoo.__session_info__ || window.odoo.session_info)) || {};
    return Boolean(s.uid && !s.is_public);
  }

  function ffShowRatingLoginHint() {
    if (!ratingSub) return;
    ratingSub.innerHTML = 'Zum Bewerten bitte im Portal anmelden';
  }

  function paintStars(avg, own, count) {
    if (!starsEl) return;
    var fill = own ? own : Math.round(avg || 0);
    var stars = starsEl.querySelectorAll('.ff-star');
    stars.forEach(function (s) {
      var v = parseInt(s.getAttribute('data-v'), 10);
      var on = (fill - v) === Math.abs(fill - v);
      s.textContent = on ? '★' : '☆';
      if (on) { s.classList.add('on'); } else { s.classList.remove('on'); }
    });
    if (!count) {
      ratingSub.textContent = ffIsLoggedIn() ? 'Sei die erste Bewertung' : '★ 1–5 Sterne für Rekordbox';
      return;
    }
    var txt = 'Ø ' + avg.toFixed(1) + ' · ' + count + (count === 1 ? ' Stimme' : ' Stimmen');
    if (own) txt = txt + ' · deine: ' + own;
    ratingSub.textContent = txt;
  }

  window.ffLoadRating = function () {
    var key = window.currentTrackKey || '';
    if (!key) return;
    fetch('/radio/rating/summary?track_id=' + encodeURIComponent(key), { cache: 'no-store' })
      .then(function (r) { return r.json(); })
      .then(function (d) {
        if (d.ok) {
          if (d.own) {
            if (starsEl) starsEl.classList.remove('locked');
          }
          paintStars(d.average || 0, d.own || 0, d.count || 0);
        }
      })
      .catch(function () {});
  };

  window.ffRate = function (stars) {
    var key = window.currentTrackKey || '';
    if (!key) return;
    if (ratingSub) ratingSub.textContent = 'Bewertung wird gespeichert …';
    fetch('/radio/rate', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ jsonrpc: '2.0', method: 'call', params: { song_id: key, stars: stars }, id: 1 })
    }).then(function (r) { return r.json(); })
      .then(function (d) {
        if (d.error) {
          ffShowRatingLoginHint();
          if (starsEl) starsEl.classList.add('locked');
          return;
        }
        var res = d.result || {};
        if (res.ok) {
          var s = res.summary || {};
          if (starsEl) starsEl.classList.remove('locked');
          paintStars(s.average || 0, s.own || 0, s.count || 0);
          if (window.spawnReaction) window.spawnReaction('⭐');
        } else if (res.reason === 'forbidden') {
          ffShowRatingLoginHint();
          if (starsEl) starsEl.classList.add('locked');
        }
      }).catch(function () {
        if (ratingSub) ratingSub.textContent = 'Bewertung konnte gerade nicht gespeichert werden';
      });
  };

  if (starsEl) {
    starsEl.classList.remove('locked');
  }
  window.ffLoadRating();
  if (window.ffLoadRedaktion) window.ffLoadRedaktion();
})();

//
(function() {
  var streamUrls = {
    '320': 'https://funk.frawo.tech/listen/frawo_funk/radio.mp3',
    '192': 'https://funk.frawo.tech/listen/frawo_funk/radio_light'
  };
  var currentQuality = '320';
  var streamUrl = streamUrls['320'];
  var reconnectAttempts = 0;
  var reconnectTimer = null;
  var API_BASE = 'https://radio-api.frawo.tech/api/v1/community';
  var AZURA_API = 'https://funk.frawo.tech/api';
  var audio = null;
  var isPlaying = false;
  var animTimer = null;
  var currentTrackKey = 'FraWo Funk';
  window.currentTrackKey = currentTrackKey;

  var visBox = document.getElementById('ff-vis-box');
  var reactCanvas = document.getElementById('ff-reaction-canvas');
  var badgeContainer = document.getElementById('ff-badge-container');
  var liveBadge = document.getElementById('ff-live-badge');

  var elDeckArt = document.getElementById('ff-deck-art');
  var elTitle = document.getElementById('ff-title');
  var elArtist = document.getElementById('ff-artist');
  var elMeta = document.getElementById('ff-meta');
  var elTicker = document.getElementById('ff-ticker');
  var elElapsed = document.getElementById('ff-elapsed');
  var elDuration = document.getElementById('ff-duration');
  var elProgFill = document.getElementById('ff-prog-fill');
  var elListeners = document.getElementById('ff-listeners');
  var elHistory = document.getElementById('ff-history');

  /* Subtle page-wide parallax: pointer devices get depth, touch stays stable. */
  var ffPage = document.querySelector('.ff-container');
  var ffPageMotion = window.matchMedia && window.matchMedia('(hover: hover) and (pointer: fine)').matches && !(window.matchMedia('(prefers-reduced-motion: reduce)').matches);
  if (ffPage && ffPageMotion) {
    ffPage.addEventListener('pointermove', function (event) {
      var rect = ffPage.getBoundingClientRect();
      var x = ((event.clientX - rect.left) / rect.width - 0.5) * 2;
      var y = ((event.clientY - rect.top) / rect.height - 0.5) * 2;
      ffPage.style.setProperty('--ff-page-x', Math.max(-1, Math.min(1, x)).toFixed(3));
      ffPage.style.setProperty('--ff-page-y', Math.max(-1, Math.min(1, y)).toFixed(3));
    });
    ffPage.addEventListener('pointerleave', function () {
      ffPage.style.setProperty('--ff-page-x', '0');
      ffPage.style.setProperty('--ff-page-y', '0');
    });
  }

  var elNextCard = document.getElementById('ff-next-card');
  var elNextBadge = document.getElementById('ff-next-badge');
  var elNextTitle = document.getElementById('ff-next-title');
  var elNextSub = document.getElementById('ff-next-sub');

  var localElapsed = 0;
  var localDuration = 0;
  var lastNowPlaying = null;
  var voteStore = {};
  var voteBannerTimeout = null;

  if (visBox) {
    if (visBox.children.length === 0) {
      for (var i = 0; i < 32; i++) {
        var bar = document.createElement('div');
        bar.className = 'ff-vis-bar';
        visBox.appendChild(bar);
      }
    }
  }

  function animateBars() {
    if (!visBox) return;
    var bars = visBox.querySelectorAll('.ff-vis-bar');
    bars.forEach(function(b) {
      if (isPlaying) {
        var h = Math.floor(Math.random() * 82) + 18;
        b.style.height = h + '%';
        b.classList.add('active');
      } else {
        b.style.height = '18%';
        b.classList.remove('active');
      }
    });
  }

  /* ===== Beat-Visual =====
     Liest die echten Pegel aus dem globalen Dauerplayer und schreibt sie als
     CSS-Variablen. Dadurch reagiert die ganze Seite (Licht, Rahmen, Glanz) im
     Takt, ohne dass Text oder Kacheln ihre Position veraendern.
     Liefert die Analyse nichts (alter Browser, Ton nicht gestartet), bleibt
     alles ruhig und die Balken laufen wie bisher im Zufallsmuster weiter. */
  var ffWurzel = document.documentElement;
  var ffBeatGlatt = 0;
  var ffAnalyseLaeuft = false;
  var ffBewegungReduziert = false;
  var ffOffenerWunsch = null;   /* Klick/Schieber, der auf den Dauerplayer wartet */
  var ffLetzterStatus = null;   /* damit die Oberflaeche nur bei Wechsel nachzieht */
  var ffOhneDatenSeit = 0;      /* Bildlaeufe ohne Tonanalyse trotz laufender Musik */
  try {
    ffBewegungReduziert = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  } catch (e) {}

  /* Holt den Wahrheitsstand vom globalen Dauerplayer und zieht die Oberflaeche
     der Radioseite nach. Nur hier wird Play/Pause-Optik entschieden -- so kann
     die Seite nicht behaupten, es laufe etwas, wenn der Player pausiert ist. */
  function syncPersistentPlayerState() {
    if (!window.fwAudio) return;
    if (typeof window.fwAudio.getState !== 'function') return;
    var zustand = window.fwAudio.getState();
    if (zustand.isPlaying === ffLetzterStatus) return;
    ffLetzterStatus = zustand.isPlaying;
    if (zustand.isPlaying) {
      startAnimation();
    } else {
      stopAnimation();
    }
  }

  /* Vorgemerkten Wunsch ausfuehren, sobald der Seitenfuss geladen ist. */
  function ffOffenenWunschAusfuehren() {
    if (!ffOffenerWunsch || !window.fwAudio) return;
    var wunsch = ffOffenerWunsch;
    if (wunsch.art === 'umschalten') {
      if (typeof window.fwAudio.togglePlay === 'function') {
        ffOffenerWunsch = null;
        window.fwAudio.togglePlay();
      }
    } else if (wunsch.art === 'lautstaerke') {
      if (typeof window.fwAudio.setVolume === 'function') {
        ffOffenerWunsch = null;
        window.fwAudio.setVolume(wunsch.wert);
      }
    }
  }

  function ffBalkenAusTon(daten) {
    if (!visBox) return;
    var bars = visBox.querySelectorAll('.ff-vis-bar');
    var anzahl = bars.length;
    if (!anzahl) return;
    /* Nur das musikalisch interessante untere Drittel des Spektrums nutzen,
       darueber ist bei 320 kbps kaum noch Pegel. */
    var nutzbar = Math.floor(daten.length * 0.62);
    for (var i = 0; i < anzahl; i++) {
      var von = Math.floor(i * nutzbar / anzahl);
      var bis = Math.max(von + 1, Math.floor((i + 1) * nutzbar / anzahl));
      var summe = 0;
      for (var j = von; j < bis; j++) summe += daten[j];
      var wert = (summe / (bis - von)) / 255;
      bars[i].style.height = Math.max(18, Math.min(100, 18 + wert * 95)) + '%';
      bars[i].classList.add('active');
    }
  }

  function ffVisualFrame() {
    ffOffenenWunschAusfuehren();
    syncPersistentPlayerState();

    if (ffBewegungReduziert) {
      /* Ruhige Seite: nur Steuerung und Statusabgleich, kein Puls. */
      requestAnimationFrame(ffVisualFrame);
      return;
    }

    var pegel = null;
    if (window.fwAudio) {
      if (typeof window.fwAudio.getLevels === 'function') {
        pegel = window.fwAudio.getLevels();
      }
    }

    var laeuft = false;
    if (window.fwAudio) {
      if (typeof window.fwAudio.getState === 'function') {
        laeuft = window.fwAudio.getState().isPlaying === true;
      }
    }

    var echteDaten = Boolean(pegel && pegel.gesamt > 0);

    if (echteDaten) {
      ffOhneDatenSeit = 0;
      ffBeatGlatt = ffBeatGlatt * 0.70 + pegel.gesamt * 0.30;
      ffWurzel.style.setProperty('--ff-bass', pegel.bass.toFixed(3));
      ffWurzel.style.setProperty('--ff-mid', pegel.mitte.toFixed(3));
      ffWurzel.style.setProperty('--ff-hi', pegel.hoehen.toFixed(3));
      ffWurzel.style.setProperty('--ff-beat', ffBeatGlatt.toFixed(3));

      var daten = window.fwAudio.getFrequencyData();
      if (daten) {
        /* Echte Tonanalyse vorhanden: der Zufallstakt wird abgeschaltet,
           damit nicht beides gleichzeitig an den Balken zieht. */
        if (!ffAnalyseLaeuft) {
          ffAnalyseLaeuft = true;
          console.log('FraWo Funk: Visual laeuft auf echten Frequenzdaten');
          if (animTimer) {
            clearInterval(animTimer);
            animTimer = null;
          }
        }
        ffBalkenAusTon(daten);
      }
    } else if (laeuft) {
      /* Es laeuft Musik, aber die Tonanalyse liefert nichts (Browser blockt
         den Audio-Kontext oder kann kein Web Audio). Dann atmet die Seite
         wenigstens ruhig weiter, statt totzuwirken. Kein Beat, bewusst langsam. */
      ffOhneDatenSeit++;
      if (ffOhneDatenSeit === 90) {
        console.log('FraWo Funk: keine Tonanalyse -- Visual atmet im Ersatzmodus');
      }
      var welle = 0.18 + 0.14 * (0.5 + 0.5 * Math.sin(Date.now() / 900));
      ffWurzel.style.setProperty('--ff-beat', welle.toFixed(3));
      ffWurzel.style.setProperty('--ff-bass', (welle * 0.8).toFixed(3));
      ffWurzel.style.setProperty('--ff-mid', (welle * 0.5).toFixed(3));
      ffWurzel.style.setProperty('--ff-hi', (welle * 0.3).toFixed(3));
    } else {
      ffOhneDatenSeit = 0;
      ffWurzel.style.setProperty('--ff-beat', '0');
      ffWurzel.style.setProperty('--ff-bass', '0');
      ffWurzel.style.setProperty('--ff-mid', '0');
      ffWurzel.style.setProperty('--ff-hi', '0');
    }

    requestAnimationFrame(ffVisualFrame);
  }

  function startAnimation() {
    isPlaying = true;
    var ico = document.getElementById('ff-play-ico');
    var txt = document.getElementById('ff-play-txt');
    if (ico) ico.textContent = '❚❚';
    if (txt) txt.textContent = 'PAUSE';
    if (!animTimer) animTimer = setInterval(animateBars, 80);
    animateBars();
  }

  function stopAnimation() {
    isPlaying = false;
    var ico = document.getElementById('ff-play-ico');
    var txt = document.getElementById('ff-play-txt');
    if (ico) ico.textContent = '▶';
    if (txt) txt.textContent = 'LISTEN LIVE';
    if (animTimer) {
      clearInterval(animTimer);
      animTimer = null;
    }
    animateBars();
  }

  function scheduleReconnect() {
    if (!isPlaying) return;
    if (reconnectTimer) clearTimeout(reconnectTimer);
    reconnectAttempts++;
    var delay = Math.min(10000, Math.pow(2, reconnectAttempts) * 500);
    console.log('FraWo Funk: Stream reconnect in ' + delay + 'ms (attempt ' + reconnectAttempts + ')...');
    var txt = document.getElementById('ff-play-txt');
    if (txt && isPlaying) txt.textContent = 'RECONNECT...';
    reconnectTimer = setTimeout(function() {
      if (!isPlaying || !audio) return;
      audio.src = streamUrl + '?t=' + Date.now();
      audio.load();
      audio.play().then(function() {
        reconnectAttempts = 0;
        startAnimation();
      }).catch(function(e) {
        console.log('Reconnect attempt failed:', e);
        scheduleReconnect();
      });
    }, delay);
  }

  window.ffToggleQuality = function() {
    currentQuality = (currentQuality === '320') ? '192' : '320';
    streamUrl = streamUrls[currentQuality];
    var btn = document.getElementById('ff-quality-btn');
    var lbl = document.getElementById('ff-quality-label');
    if (lbl) {
      lbl.textContent = (currentQuality === '320') ? '⚡ 320K HD' : '🍃 192K ECO';
    }
    if (btn) {
      if (currentQuality === '320') {
        btn.style.borderColor = 'rgba(46, 204, 113, 0.4)';
        btn.style.color = '#2ecc71';
        btn.style.background = 'rgba(46, 204, 113, 0.08)';
      } else {
        btn.style.borderColor = 'rgba(245, 158, 11, 0.4)';
        btn.style.color = '#f59e0b';
        btn.style.background = 'rgba(245, 158, 11, 0.08)';
      }
    }
    if (isPlaying && audio) {
      audio.src = streamUrl + '?t=' + Date.now();
      audio.load();
      audio.play().then(function() {
        reconnectAttempts = 0;
        startAnimation();
      }).catch(function(e) {
        console.log('Quality switch play error:', e);
      });
    }
  };

  window.ffTogglePlay = function() {
    /* Der globale Dauerplayer ist die einzige Audioinstanz. Während der
       Seitenfuß noch initialisiert, kurz warten statt einen zweiten Stream
       als lokalen Fallback zu erzeugen. */
    if (window.fwAudio && typeof window.fwAudio.togglePlay === 'function') {
      window.fwAudio.togglePlay();
      syncPersistentPlayerState();
      return;
    }
    var txt = document.getElementById('ff-play-txt');
    if (txt) txt.textContent = 'PLAYER LÄDT...';
    /* Kein Timer: der Wunsch wird vorgemerkt und im naechsten Bildlauf
       ausgefuehrt, sobald der Dauerplayer da ist. Der Klick geht nie
       verloren und wird auch nicht kuenstlich verzoegert. */
    ffOffenerWunsch = { art: 'umschalten' };
  };

  window.ffSetVolume = function(val) {
    if (window.fwAudio && typeof window.fwAudio.setVolume === 'function') {
      window.fwAudio.setVolume(val);
      return;
    }
    ffOffenerWunsch = { art: 'lautstaerke', wert: val };
  };

  function loadVotes() {
    if (window.ffLoadRating) window.ffLoadRating();
    if (window.ffLoadRedaktion) window.ffLoadRedaktion();
  }
  function renderNextTrack(np) {}

  function spawnReaction(emoji) {
    if (!reactCanvas) return;
    var el = document.createElement('div');
    el.className = 'ff-floating-emoji';
    el.textContent = emoji;
    el.style.left = (Math.random() * 80 + 10) + '%';
    reactCanvas.appendChild(el);
    setTimeout(function() { el.remove(); }, 1600);
  }
  window.spawnReaction = spawnReaction;

  function fmtTime(sec) {
    sec = Math.max(0, Math.floor(sec || 0));
    var h = Math.floor(sec / 3600);
    var m = Math.floor((sec % 3600) / 60);
    var s = sec % 60;
    if (h > 0) {
      return h + ':' + (m < 10 ? '0' : '') + m + ':' + (s < 10 ? '0' : '') + s;
    }
    return m + ':' + (s < 10 ? '0' : '') + s;
  }

  function fmtCountdown(sec) {
    sec = Math.max(0, Math.floor(sec || 0));
    var h = Math.floor(sec / 3600);
    var m = Math.floor((sec % 3600) / 60);
    var s = sec % 60;
    if (h > 0) {
      return 'in ' + h + 'h ' + m + 'm';
    }
    return 'in ' + m + ':' + (s < 10 ? '0' : '') + s;
  }

    window.ffSetMood = function(mood) {
    var key = currentTrackKey;
    if (!key) key = 'FraWo Funk';

    var btnEnergy = document.getElementById('ff-mood-energy');
    var btnBanger = document.getElementById('ff-mood-banger');
    var btnChill = document.getElementById('ff-mood-chill');
    var cntBanger = document.getElementById('ff-banger-cnt');

    if (voteBannerTimeout) clearTimeout(voteBannerTimeout);
    if (elNextCard) elNextCard.classList.add('active-vote');

    if (mood === 'energy') {
      spawnReaction('⚡');
      if (btnEnergy) {
        btnEnergy.classList.add('active');
        setTimeout(function() { btnEnergy.classList.remove('active'); }, 1200);
      }
      if (elNextBadge) elNextBadge.textContent = '⚡ DEIN VOTE AKTIV';
      if (elNextTitle) elNextTitle.textContent = 'Mehr Energie angefordert: Tempo und BPM werden erhöht!';
      if (elNextSub) elNextSub.textContent = 'Wirksam ab Track +1';

      fetch('/radio/vote', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ jsonrpc: '2.0', method: 'call', params: { song_id: key, vote_type: 'energy' }, id: 1 })
      }).catch(function() {});
    } 
    else if (mood === 'chill') {
      spawnReaction('🌙');
      if (btnChill) {
        btnChill.classList.add('active');
        setTimeout(function() { btnChill.classList.remove('active'); }, 1200);
      }
      if (elNextBadge) elNextBadge.textContent = '🌙 DEIN VOTE AKTIV';
      if (elNextTitle) elNextTitle.textContent = 'Chillout-Modus aktiv: Sanfte Downtempo- und Ambient-Tracks werden priorisiert!';
      if (elNextSub) elNextSub.textContent = 'Wirksam ab Track +1';

      fetch('/radio/vote', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ jsonrpc: '2.0', method: 'call', params: { song_id: key, vote_type: 'chill' }, id: 1 })
      }).catch(function() {});
    } 
    else if (mood === 'banger') {
      var prevVote = localStorage.getItem('ff_banger_' + key);
      var newVote = (prevVote === 'up') ? null : 'up';

      if (newVote) {
        localStorage.setItem('ff_banger_' + key, 'up');
        if (btnBanger) btnBanger.classList.add('active');
        spawnReaction('🔥');
        if (cntBanger) {
          var cur = parseInt(cntBanger.textContent, 10) || 0;
          cntBanger.textContent = cur + 1;
        }
        if (elNextBadge) elNextBadge.textContent = '🔥 BANGER VOTE';
        if (elNextTitle) elNextTitle.textContent = 'Track als Banger markiert: In Rotation priorisiert!';
        if (elNextSub) elNextSub.textContent = 'Live im Studio registriert';
      } else {
        localStorage.removeItem('ff_banger_' + key);
        if (btnBanger) btnBanger.classList.remove('active');
        if (cntBanger) {
          var cur = parseInt(cntBanger.textContent, 10) || 1;
          cntBanger.textContent = Math.max(0, cur - 1);
        }
      }

      fetch('/radio/vote', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ jsonrpc: '2.0', method: 'call', params: { song_id: key, vote_type: (newVote ? 'like' : 'unlike') }, id: 1 })
      }).catch(function() {});
    }

    voteBannerTimeout = setTimeout(function() {
      voteBannerTimeout = null;
      if (elNextCard) elNextCard.classList.remove('active-vote');
      if (typeof loadNowPlaying === 'function') loadNowPlaying();
    }, 6500);
  };

  window.ffExportBangers = function() {
    var bangers = [];
    for (var i = 0; i < localStorage.length; i++) {
      var k = localStorage.key(i);
      if (k) {
        if (k.indexOf('ff_banger_') === 0) {
          if (localStorage.getItem(k) === 'up') {
            var raw = k.replace('ff_banger_', '');
            var parts = raw.split('|');
            var art = parts[0] || 'Unbekannt';
            var tit = parts[1] || 'Unbekannt';
            bangers.push({ artist: art, title: tit });
          }
        }
      }
    }

    if (bangers.length === 0) {
      alert('Du hast noch keine Tracks als Banger (❤️) markiert.\nKlicke bei deinen Lieblingstracks auf ❤️ Banger, um deine persönliche DJ-Playlist aufzubauen!');
      return;
    }

    var m3u = '#EXTM3U\n#EXTENC:UTF-8\n#PLAYLIST:FraWo Funk - Meine Rekordbox Bangers\n\n';
    bangers.forEach(function(b, idx) {
      m3u += '#EXTINF:300,' + b.artist + ' - ' + b.title + '\n';
      m3u += '# FraWo Funk Voted Banger #' + (idx + 1) + '\n';
      m3u += 'https://funk.frawo.tech/listen/frawo_funk/radio.mp3\n\n';
    });

    var blob = new Blob([m3u], { type: 'audio/x-mpegurl;charset=utf-8' });
    var url = URL.createObjectURL(blob);
    var a = document.createElement('a');
    a.href = url;
    a.download = 'FraWo_Funk_Rekordbox_Bangers.m3u';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  var reqSearch = document.getElementById('ff-req-search');
  var reqResults = document.getElementById('ff-req-results');
  var reqDebounce = null;

  if (reqSearch) {
    reqSearch.addEventListener('input', function() {
      var q = reqSearch.value.trim();
      if (reqDebounce) clearTimeout(reqDebounce);
      if (q.length < 2) {
        if (reqResults) reqResults.innerHTML = '<div style="font-family:monospace;font-size:0.72rem;color:#64748b;padding:6px 0;">Tippe mindestens 2 Zeichen ein, um passende Tracks zur aktuellen Show zu suchen und einzureihen.</div>';
        return;
      }

      reqDebounce = setTimeout(function() {
        fetch(AZURA_API + '/station/1/requests?searchPhrase=' + encodeURIComponent(q))
          .then(function(r) { return r.json(); })
          .then(function(list) {
            if (!reqResults) return;
            if (!Array.isArray(list) || list.length === 0) {
              reqResults.innerHTML = '<div style="font-family:monospace;font-size:0.75rem;color:#94a3b8;padding:8px 0;">Kein passender Track in der aktuellen Show für "' + q.replace(/</g, '<') + '".</div>';
              return;
            }

            var html = '';
            list.slice(0, 8).forEach(function(m) {
              var s = m.song || {};
              html += '<div class="ff-req-item">' +
                        '<div class="ff-req-meta">' +
                          '<div class="ff-req-title">' + (s.title || 'Unbekannt') + '</div>' +
                          '<div class="ff-req-artist">' + (s.artist || '') + '</div>' +
                        '</div>' +
                        '<button class="ff-req-btn" data-req-id="' + m.request_id + '">+ Wunsch</button>' +
                      '</div>';
            });
            reqResults.innerHTML = html;
          })
          .catch(function(e) {
            if (reqResults) reqResults.innerHTML = '<div style="font-family:monospace;font-size:0.75rem;color:#94a3b8;padding:8px 0;">Wunsch-System lädt...</div>';
          });
      }, 300);
    });
  }

  if (reqResults) {
    reqResults.addEventListener('click', function(ev) {
      var btn = ev.target.closest('.ff-req-btn');
      if (!btn) return;
      if (btn.classList.contains('done')) return;
      var reqId = btn.getAttribute('data-req-id');
      btn.textContent = '...';
      fetch(AZURA_API + '/station/1/request/' + encodeURIComponent(reqId), { method: 'POST' })
        .then(function(r) { return r.json(); })
        .then(function(res) {
          if (res.success) {
            btn.textContent = '✓ Eingereiht';
            btn.classList.add('done');
            spawnReaction('💜');
          } else {
            btn.textContent = res.message || 'Cooldown aktiv';
          }
        })
        .catch(function() {
          btn.textContent = 'Eingereiht';
          btn.classList.add('done');
        });
    });
  }

  setInterval(function() {
    if (localDuration > 0) {
      if (localElapsed < localDuration) {
        localElapsed = localElapsed + 1;
        if (elProgFill) elProgFill.style.width = (100 * localElapsed / localDuration) + '%';
        if (elElapsed) elElapsed.textContent = fmtTime(localElapsed);
        if (elNextSub) {
          if (!voteBannerTimeout) {
            var rem = Math.max(0, localDuration - localElapsed);
            elNextSub.textContent = fmtCountdown(rem);
          }
        }
      }
    }
  }, 1000);

  var histRatingsCache = {};

  window.ffRateHistory = function(key, stars, targetEl) {
    fetch('/radio/rate', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ jsonrpc: '2.0', method: 'call', params: { song_id: key, stars: stars }, id: Date.now() })
    })
    .then(function(r) { return r.json(); })
    .then(function(d) {
      if (d.error || (d.result && !d.result.ok)) {
        alert('Zum Bewerten bitte im Portal anmelden. Deine Bewertungen fließen direkt in Rekordbox ein!');
        return;
      }
      var res = d.result || {};
      if (res.ok) {
        var s = res.summary || {};
        histRatingsCache[key] = s;
        if (targetEl) updateHistStarsEl(targetEl, s.average || 0, s.own || stars, s.count || 0);
        if (window.spawnReaction) window.spawnReaction('⭐');
      }
    }).catch(function() {});
  };

  function updateHistStarsEl(wrap, avg, own, count) {
    if (!wrap) return;
    var starsSpans = wrap.querySelectorAll('.ff-hstar');
    var scoreEl = wrap.querySelector('.ff-hist-score');
    var rounded = Math.round(avg || own || 0);
    starsSpans.forEach(function(sp, idx) {
      var v = idx + 1;
      var active = Boolean(Math.max(v, rounded) === rounded);
      sp.textContent = active ? '★' : '☆';
      sp.style.color = active ? '#f59e0b' : '#64748b';
    });
    if (scoreEl) {
      scoreEl.textContent = avg ? ('Ø ' + Number(avg).toFixed(1)) : 'Neu';
    }
  }

  window.renderHistory = function(list) {
    if (!elHistory) return;
    if (!list) return;
    elHistory.innerHTML = '';
    list.forEach(function(item) {
      var song = item.song || {};
      var div = document.createElement('div');
      div.className = 'ff-hist-item';
      var art = song.art || '/web/image/2195';
      var title = song.title || 'Unbekannt';
      var artist = song.artist || 'Studio Stream';
      var key = artist + '|' + title;

      var safeTitle = title.replace(/"/g, '');
      var safeArtist = artist.replace(/"/g, '');

      div.innerHTML =
        '<img class="ff-hist-art" src="' + art + '" alt="Cover: ' + safeArtist + ' – ' + safeTitle + '" loading="lazy"/>' +
        '<div class="ff-hist-title" title="' + safeTitle + '">' + title + '</div>' +
        '<div class="ff-hist-artist" title="' + safeArtist + '">' + artist + '</div>' +
        '<div class="ff-hist-rating">' +
          '<div class="ff-hist-stars">' +
            '<span class="ff-hstar" data-v="1" title="1 Stern">☆</span>' +
            '<span class="ff-hstar" data-v="2" title="2 Sterne">☆</span>' +
            '<span class="ff-hstar" data-v="3" title="3 Sterne">☆</span>' +
            '<span class="ff-hstar" data-v="4" title="4 Sterne">☆</span>' +
            '<span class="ff-hstar" data-v="5" title="5 Sterne">☆</span>' +
          '</div>' +
          '<span class="ff-hist-score">...</span>' +
        '</div>';

      var ratingWrap = div.querySelector('.ff-hist-rating');
      var starEls = div.querySelectorAll('.ff-hstar');
      starEls.forEach(function(sEl) {
        sEl.addEventListener('click', function(e) {
          e.stopPropagation();
          var v = parseInt(sEl.getAttribute('data-v'), 10);
          window.ffRateHistory(key, v, ratingWrap);
        });
      });

      if (histRatingsCache[key]) {
        var cached = histRatingsCache[key];
        updateHistStarsEl(ratingWrap, cached.average || 0, cached.own || 0, cached.count || 0);
      } else {
        fetch('/radio/rating/summary?track_id=' + encodeURIComponent(key), { cache: 'no-store' })
          .then(function(r) { return r.json(); })
          .then(function(d) {
            if (d && d.ok) {
              histRatingsCache[key] = d;
              updateHistStarsEl(ratingWrap, d.average || 0, d.own || 0, d.count || 0);
            }
          }).catch(function() {});
      }

      elHistory.appendChild(div);
    });
  };

  function loadNowPlaying() {
    fetch(AZURA_API + '/nowplaying/1')
      .then(function(r) { return r.json(); })
      .then(function(data) {
        var np = data.now_playing;
        var live = data.live || {};
        if (window.ffSetLiveMode) window.ffSetLiveMode(!!live.is_live);

        if (live.is_live) {
          if (badgeContainer) {
            if (liveBadge) {
              badgeContainer.classList.add('dj-takeover');
              liveBadge.textContent = 'LIVE DJ: ' + (live.streamer_name || 'WOLF PRINZ');
            }
          }
        } else if (badgeContainer) {
          if (liveBadge) {
            badgeContainer.classList.remove('dj-takeover');
            liveBadge.textContent = 'ON AIR JETZT';
          }
        }

        if (np) {
          if (np.song) {
            if (np.song.title) {
              lastNowPlaying = np;
              if (elTitle) elTitle.textContent = np.song.title || 'FraWo Funk';
              if (elDeckArt) elDeckArt.src = np.song.art || '/web/image/2195';

              if ('mediaSession' in navigator) {
                navigator.mediaSession.metadata = new MediaMetadata({
                  title: np.song.title || 'FraWo Funk',
                  artist: np.song.artist || 'Studio Stream',
                  album: np.song.album || 'FraWo Studio Bodensee',
                  artwork: [
                    { src: np.song.art || '/web/image/2195', sizes: '512x512', type: 'image/jpeg' }
                  ]
                });
                navigator.mediaSession.setActionHandler('play', function() { window.ffTogglePlay(); });
                navigator.mediaSession.setActionHandler('pause', function() { window.ffTogglePlay(); });
              }

              if (elArtist) elArtist.textContent = np.song.artist || 'Studio Stream';
              if (np.playlist) {
                window.ffCurrentSendung = np.playlist;
                var showTag = document.getElementById('ff-show-tag');
                if (showTag) {
                  showTag.textContent = '📻 SHOW: ' + np.playlist.toUpperCase();
                }
              } else {
                window.ffCurrentSendung = '';
                var showTagLeer = document.getElementById('ff-show-tag');
                if (showTagLeer) {
                  showTagLeer.textContent = '📻 SHOW: LIVE';
                }
              }
              if (elMeta) {
                var metaBits = [];
                if (np.song.genre) metaBits.push(np.song.genre);
                if (np.song.album) metaBits.push(np.song.album);
                elMeta.textContent = metaBits.length ? metaBits.join(' · ') : '—';
              }

              var newKey = (np.song.artist || '') + '|' + (np.song.title || '');
              if (newKey !== currentTrackKey) {
                currentTrackKey = newKey;
                window.currentTrackKey = newKey;
                loadVotes();
              }

              if (np.duration > 0) {
                if (np.elapsed >= 0) {
                  if (np.elapsed <= np.duration + 5) {
                    localElapsed = np.elapsed;
                    localDuration = np.duration;
                    if (elDuration) elDuration.textContent = fmtTime(localDuration);
                    if (elElapsed) elElapsed.textContent = fmtTime(localElapsed);
                    if (elProgFill) elProgFill.style.width = (100 * localElapsed / localDuration) + '%';
                  }
                }
              }

              if (data.listeners) {
                if (elListeners) {
                  elListeners.textContent = data.listeners.total || data.listeners.current || 1;
                }
              }

              if (data.song_history) { window.lastSongHistory = data.song_history;
                renderHistory(data.song_history.slice(0, 6));
              }

              if (!voteBannerTimeout) {
                if (data.playing_next) {
                  if (data.playing_next.song) {
                    var next = data.playing_next;
                    if (elNextBadge) elNextBadge.textContent = '▶ ALS NÄCHSTES';
                    if (elNextTitle) elNextTitle.textContent = (next.song.artist || '') + ' — ' + (next.song.title || '');
                    var rem = Math.max(0, localDuration - localElapsed);
                    if (elNextSub) elNextSub.textContent = (rem > 0) ? fmtCountdown(rem) : 'demnächst';
                  }
                }
              }

              if (np.playlist) {
                highlightSchedule(np.playlist);
              } else {
                updateTicker();
              }
            }
          }
        }
      })
      .catch(function(e) {
        console.log('NowPlaying error:', e);
      });
  }

  function updateTicker() {
    if (!elTicker) return;
    var showName = null;
    if (lastNowPlaying) {
      if (lastNowPlaying.playlist) {
        showName = lastNowPlaying.playlist;
      }
    }
    if (!showName) {
      var activeCard = document.querySelector('#ff-schedule .active-slot .ff-card-name');
      showName = activeCard ? activeCard.textContent : 'FraWo Funk';
    }
    var parts = [];
    if (lastNowPlaying) {
      if (lastNowPlaying.song) {
        parts.push('● JETZT LÄUFT: ' + lastNowPlaying.song.artist + ' – ' + lastNowPlaying.song.title);
      }
    }
    parts.push('● SHOW: ' + showName);
    parts.push('● FRAWO FUNK · 24/7 LIVE');
    while (elTicker.firstChild) {
      elTicker.removeChild(elTicker.firstChild);
    }
    parts.forEach(function (part, idx) {
      if (idx !== 0) {
        var sep = document.createElement('span');
        sep.textContent = '//';
        elTicker.appendChild(sep);
      }
      elTicker.appendChild(document.createTextNode(part));
    });
  }

  // Sendeplan live: Wochenreiter + Tagesplan werden aus /radio/schedule gebaut.
  // Ohne spitze Klammern oder Et-Zeichen im Quelltext (Vorgabe Task 5, gueltiges XML).
  var FF_TAGE = [
    { tag: 1, kurz: 'MO' },
    { tag: 2, kurz: 'DI' },
    { tag: 3, kurz: 'MI' },
    { tag: 4, kurz: 'DO' },
    { tag: 5, kurz: 'FR' },
    { tag: 6, kurz: 'SA' },
    { tag: 0, kurz: 'SO' }
  ];
  var ffScheduleData = [];

  function ffWochentag(isoStart) {
    // Tagesbestimmung aus dem Datumsteil des ISO-Strings (bereits
    // Europe/Berlin, siehe Route), NICHT ueber new Date(iso).getDay() --
    // das wuerde im Browser-Zeitzonen-Kontext neu interpretiert.
    var jahr = parseInt(isoStart.substr(0, 4), 10);
    var monat = parseInt(isoStart.substr(5, 2), 10);
    var tag = parseInt(isoStart.substr(8, 2), 10);
    return new Date(jahr, monat - 1, tag).getDay();
  }

  function ffZeit(iso) {
    return iso ? iso.substr(11, 5) : '';
  }

  function ffBerlinHeute() {
    // Fallback, wenn kein jetzt-Eintrag vorliegt: heutiges Datum in
    // Europe/Berlin ueber Intl (nicht Browser-Ortszeit), dieselbe sichere
    // Konstruktion wie ffWochentag (lokaler Date-Konstruktor aus Y/M/D,
    // keine erneute Zeitzonen-Interpretation eines Instant-Strings).
    var teile = new Intl.DateTimeFormat('en-CA', {
      timeZone: 'Europe/Berlin', year: 'numeric', month: '2-digit', day: '2-digit'
    }).format(new Date());
    var jahr = parseInt(teile.substr(0, 4), 10);
    var monat = parseInt(teile.substr(5, 2), 10);
    var tag = parseInt(teile.substr(8, 2), 10);
    return new Date(jahr, monat - 1, tag).getDay();
  }

  function ffHeuteTag() {
    // "Heute" konsistent mit ffWochentag aus den Serverdaten ableiten, nicht
    // aus (new Date()).getDay() (Browser-Ortszeit) -- sonst zeigt die Seite
    // fuer Besucher ausserhalb Europe/Berlin nahe der Tagesgrenze den
    // falschen Reiter bzw. markiert die laufende Sendung nicht.
    var jetztEintrag = null;
    ffScheduleData.forEach(function (e) {
      if (e.jetzt) jetztEintrag = e;
    });
    if (jetztEintrag) {
      return ffWochentag(jetztEintrag.start);
    }
    return ffBerlinHeute();
  }

  function ffZeigeSendeplanFehler() {
    var box = document.getElementById('ff-schedule-live');
    if (!box) return;
    box.textContent = '';
    var hinweis = document.createElement('div');
    hinweis.className = 'ff-schedule-hint';
    hinweis.textContent = 'Sendeplan gerade nicht erreichbar';
    box.appendChild(hinweis);
  }

  function ffZeigeTag(tagNum) {
    var tabs = Array.prototype.slice.call(document.querySelectorAll('#ff-week-tabs .ff-week-tab'));
    tabs.forEach(function (t) {
      var d = parseInt(t.getAttribute('data-day'), 10);
      t.classList.toggle('active', d === tagNum);
    });
    var panels = Array.prototype.slice.call(document.querySelectorAll('#ff-schedule .ff-day-panel'));
    panels.forEach(function (p) {
      var d = parseInt(p.getAttribute('data-day'), 10);
      p.classList.toggle('active', d === tagNum);
    });
  }

  function ffBuildSchedule(eintraege) {
    var box = document.getElementById('ff-schedule-live');
    if (!box) return;
    ffScheduleData = eintraege || [];

    if (ffScheduleData.length === 0) {
      ffZeigeSendeplanFehler();
      return;
    }

    var eimer = { 0: [], 1: [], 2: [], 3: [], 4: [], 5: [], 6: [] };
    ffScheduleData.forEach(function (e) {
      eimer[ffWochentag(e.start)].push(e);
    });

    var heute = ffHeuteTag();

    box.textContent = '';

    var jetztEintrag = null;
    ffScheduleData.forEach(function (e) {
      if (e.jetzt) jetztEintrag = e;
    });
    if (jetztEintrag) {
      var liveProgram = document.getElementById('ff-live-program-show');
      if (liveProgram) {
        liveProgram.textContent = 'Jetzt: ' + jetztEintrag.name + ' · ' + ffZeit(jetztEintrag.start) + '–' + ffZeit(jetztEintrag.ende) + ' Uhr';
      }
      var idx = ffScheduleData.indexOf(jetztEintrag);
      var danach = ffScheduleData[idx + 1];
      if (danach) {
        var danachZeile = document.createElement('div');
        danachZeile.className = 'ff-schedule-danach';
        danachZeile.textContent = 'Danach: ' + danach.name + ' ab ' + ffZeit(danach.start) + ' Uhr';
        box.appendChild(danachZeile);
      }
    } else {
      var keinLiveProgram = document.getElementById('ff-live-program-show');
      if (keinLiveProgram) keinLiveProgram.textContent = 'Live-Sendeplan wird aktualisiert …';
    }

    var tabs = document.createElement('div');
    tabs.className = 'ff-week-tabs';
    tabs.id = 'ff-week-tabs';

    var panelsWrap = document.createElement('div');
    panelsWrap.id = 'ff-schedule';

    FF_TAGE.forEach(function (info) {
      var btn = document.createElement('button');
      btn.className = 'ff-week-tab';
      btn.setAttribute('data-day', String(info.tag));

      var spanTag = document.createElement('span');
      spanTag.className = 'ff-tab-day';
      spanTag.textContent = info.kurz;
      btn.appendChild(spanTag);

      var tagesEintraege = eimer[info.tag];

      var spanSub = document.createElement('span');
      spanSub.className = 'ff-tab-sub';
      spanSub.textContent = tagesEintraege[0] ? tagesEintraege[0].name : '';
      btn.appendChild(spanSub);

      if (info.tag === heute) {
        btn.classList.add('today');
      }
      btn.addEventListener('click', function () {
        ffZeigeTag(info.tag);
      });
      tabs.appendChild(btn);

      var panel = document.createElement('div');
      panel.className = 'ff-day-panel';
      panel.setAttribute('data-day', String(info.tag));

      if (tagesEintraege.length === 0) {
        var leer = document.createElement('div');
        leer.className = 'ff-schedule-hint';
        leer.textContent = 'Für diesen Tag liegen aktuell keine Daten vom Sender vor.';
        panel.appendChild(leer);
      } else {
        tagesEintraege.forEach(function (e) {
          var card = document.createElement('div');
          card.className = 'ff-card';
          card.setAttribute('data-show', e.name);
          card.setAttribute('data-day', String(info.tag));
          if (e.jetzt) {
            card.classList.add('active-slot', 'live-now');
          }

          var inner = document.createElement('div');

          var zeit = document.createElement('div');
          zeit.className = 'ff-card-time';
          zeit.textContent = ffZeit(e.start) + ' – ' + ffZeit(e.ende);
          inner.appendChild(zeit);

          var name = document.createElement('div');
          name.className = 'ff-card-name';
          name.textContent = e.name;
          inner.appendChild(name);

          if (e.beschreibung) {
            var desc = document.createElement('div');
            desc.className = 'ff-card-desc';
            desc.textContent = e.beschreibung;
            inner.appendChild(desc);
          }

          card.appendChild(inner);
          panel.appendChild(card);
        });
      }

      panelsWrap.appendChild(panel);
    });

    box.appendChild(tabs);
    box.appendChild(panelsWrap);

    ffZeigeTag(heute);
    updateTicker();
  }

  function ffLoadSchedule() {
    fetch('/radio/schedule', { cache: 'no-store' })
      .then(function (r) {
        if (!r.ok) throw new Error('http-' + r.status);
        return r.json();
      })
      .then(function (daten) {
        ffBuildSchedule(daten);
      })
      .catch(function () {
        ffZeigeSendeplanFehler();
      });
  }

  function highlightSchedule(currentPlaylist) {
    var ziel = currentPlaylist || (lastNowPlaying ? lastNowPlaying.playlist : null);
    if (ziel) {
      var zielTief = ziel.toLowerCase();
      var heute = ffHeuteTag();
      var karten = Array.prototype.slice.call(document.querySelectorAll('#ff-schedule .ff-card'));
      karten.forEach(function (c) {
        var istHeute = parseInt(c.getAttribute('data-day'), 10) === heute;
        var showAttr = (c.getAttribute('data-show') || '').toLowerCase();
        var treffer = istHeute ? (showAttr === zielTief) : false;
        c.classList.toggle('active-slot', treffer);
        c.classList.toggle('live-now', treffer);
      });
    }
    updateTicker();
  }

  ffLoadSchedule();
  loadNowPlaying();
  loadVotes();
  setInterval(loadNowPlaying, 5000);
  setInterval(ffLoadSchedule, 60000);

  /* Bildlauf immer starten: er fuehrt vorgemerkte Klicks aus und haelt die
     Oberflaeche am Dauerplayer. Der Puls selbst bleibt aus, wenn der Besucher
     reduzierte Bewegung eingestellt hat. */
  requestAnimationFrame(ffVisualFrame);
})();
